- lower: p = right tail. num > 0 → t=+∞ → p=0. num < 0 → t=−∞ → p=1. num == 0 → p=1. So p = num > 0 ? 0 : 1. ✓
- upper: p = left tail. num > 0 → t=+∞ → p=1. num < 0 → p=0. num == 0 → p=1. So p = num < 0 ? 0 : 1. ✓

And tRightTailP/tLeftTailP:

```js
// t 分布右尾概率 P(T >= t)：t >= 0 时为双侧尾概率的一半，
// t < 0 时由对称性 1 - P(T >= -t)。与 tTwoTailedP 同一口径。
function tRightTailP(df, t) {
  if (t >= 0) return tTwoTailedP(df, t) / 2;
  return 1 - tTwoTailedP(df, -t) / 2;
}

// t 分布左尾概率 P(T <= t)，由右尾对称得到。
function tLeftTailP(df, t) {
  return tRightTailP(df, -t);
}
```

