// TOST 等价性检验（两个单侧 Welch t 检验）：diff 为候选均值减基线均值，
// margin > 0 为等价边界（与 diff 同单位）。
// lower 检验 diff > -margin：t = (diff + margin)/se，p_value 取右尾；
// upper 检验 diff < +margin：t = (diff - margin)/se，p_value 取左尾；
// degrees_of_freedom 为 Welch 自由度，两检验共用。数值保留六位小数。
// 两边方差均为 0 的退化情形（se 为 0）：按分子符号定 p——
// diff 严格在 (-margin, margin) 内时两 p 均为 0；等于任一边界时对应检验
// p 为 1（另一为 0）；越界时一侧为 0、另一侧为 1。
// 此时 t_statistic 在分子为 0 时为 0、否则为 null，degrees_of_freedom 为 null。
function equivalenceTest(baseline, candidate, margin) {
  const n1 = baseline.length;
  const n2 = candidate.length;
  const m1 = meanOf(baseline);
  const m2 = meanOf(candidate);
  const v1 = sampleVariance(baseline, m1);
  const v2 = sampleVariance(candidate, m2);
  const diff = m2 - m1;

  if (v1 === 0 && v2 === 0) {
    const lowerNum = diff + margin;
    const upperNum = diff - margin;
    return {
      lower: {
        t_statistic: lowerNum === 0 ? 0 : null,
        p_value: lowerNum > 0 ? 0 : 1,
      },
      upper: {
        t_statistic: upperNum === 0 ? 0 : null,
        p_value: upperNum < 0 ? 0 : 1,
      },
      degrees_of_freedom: null,
    };
  }

  const s1 = v1 / n1;
  const s2 = v2 / n2;
  const standardError = Math.sqrt(s1 + s2);
  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
  const lowerT = (diff + margin) / standardError;
  const upperT = (diff - margin) / standardError;
  return {
    lower: {
      t_statistic: round6(lowerT),
      p_value: round6(tRightTailP(df, lowerT)),
    },
    upper: {
      t_statistic: round6(upperT),
      p_value: round6(tLeftTailP(df, upperT)),
    },
    degrees_of_freedom: round6(df),
  };
}

// ---- Mann-Whitney U 双侧检验 ----

